// Stand-ins for real model responses, covering failure shapes seen in practice.
const fence = '`'.repeat(3);
return [
  { case: 'clean array', raw: '[{"title":"Pricing guide","target_keyword":"n8n pricing","search_intent":"commercial"}]' },
  { case: 'markdown fence', raw: fence + 'json\n[{"title":"Setup","target_keyword":"self-host n8n","search_intent":"informational"}]\n' + fence },
  { case: 'single object', raw: '{"title":"Error handling","target_keyword":"n8n error trigger","search_intent":"informational"}' },
  { case: 'truncated', raw: '[{"title":"Retries","target_keyword":"n8n retry' },
  { case: 'prose only', raw: 'Sure! Here are some great content ideas for your site.' },
  { case: 'wrong fields', raw: '[{"title":"Queues","keyword":"n8n queue mode","search_intent":"curious"}]' },
].map(json => ({ json }));

const REQUIRED = { title: 'string', target_keyword: 'string', search_intent: 'string' };
const INTENTS = new Set(['informational', 'commercial', 'transactional', 'navigational']);

// Find the text wherever the model node put it.
const raw = String($json.raw ?? $json.text ?? $json.output ?? '');
const errors = [];
let parsed;

// Strip markdown fences and anything before the first bracket.
const cleaned = raw.replace(/```(?:json)?/gi, '').trim();
const start = cleaned.search(/[\[{]/);
if (start === -1) {
  errors.push('no JSON found in model output');
} else {
  try {
    parsed = JSON.parse(cleaned.slice(start));
  } catch (e) {
    errors.push(`invalid JSON: ${e.message}`);
  }
}

// Accept a single object as a one-item array, as the original parser did.
const records = parsed === undefined ? [] : (Array.isArray(parsed) ? parsed : [parsed]);
if (parsed !== undefined && records.length === 0) errors.push('empty array');

records.forEach((r, i) => {
  if (typeof r !== 'object' || r === null) { errors.push(`item ${i}: not an object`); return; }
  for (const [field, type] of Object.entries(REQUIRED)) {
    if (typeof r[field] !== type || String(r[field]).trim() === '') errors.push(`item ${i}: ${field} missing or not a ${type}`);
  }
  if (typeof r.search_intent === 'string' && !INTENTS.has(r.search_intent.toLowerCase())) {
    errors.push(`item ${i}: unexpected search_intent "${r.search_intent}"`);
  }
});

return {
  json: {
    case: $json.case ?? null,
    valid: errors.length === 0,
    errors,
    records: errors.length === 0 ? records : [],
    raw_preview: raw.slice(0, 300),
  },
};
